function zipLongestFill(a, b, fill = null) {
  const maxLen = Math.max(a.length, b.length);
  return Array.from({length: maxLen}, (_, i) => [a[i] ?? fill, b[i] ?? fill]);
}
console.log(zipLongestFill([1,2], ['a','b','c','d']));
